#![allow(unused_imports)]
use verus::prelude::*;

/// Pure helper: absolute value of an i8
#[verus::pure]
fn abs_i8(x: i8) -> i8 {
    if x >= 0 { x } else { -x }
}

/// Pure function computing the minimum rook moves on an 8×8 board.
#[verus::pure]
fn rook_moves(r1: i8, c1: i8, r2: i8, c2: i8) -> i8 {
    if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    }
}

/// Pure function computing the minimum bishop moves on an 8×8 board.
/// Returns 0 if unreachable (different color) or same square,
/// 1 if on the same diagonal,
/// 2 if same color but not on the same diagonal.
#[verus::pure]
fn bishop_moves(r1: i8, c1: i8, r2: i8, c2: i8) -> i8 {
    if r1 == r2 && c1 == c2 {
        0
    } else if abs_i8(r1 - r2) == abs_i8(c1 - c2) {
        1
    } else if ((r1 + c1) % 2) == ((r2 + c2) % 2) {
        2
    } else {
        0
    }
}

/// Pure function computing the minimum king moves (Chebyshev distance).
#[verus::pure]
fn king_moves(r1: i8, c1: i8, r2: i8, c2: i8) -> i8 {
    let dr = abs_i8(r1 - r2);
    let dc = abs_i8(c1 - c2);
    if dr >= dc { dr } else { dc }
}

/// Verus‐verified solution function.
///
/// # Requirements
/// * 1 <= r1, c1, r2, c2 <= 8
///
/// # Ensures
/// * Returns a length‐3 Vec.
/// * result[0] == minimum rook moves.
/// * result[1] == minimum bishop moves (0 if unreachable or same square).
/// * result[2] == minimum king moves.
#[verus::verified]
#[verus::requires(
    1 <= r1 && r1 <= 8,
    1 <= c1 && c1 <= 8,
    1 <= r2 && r2 <= 8,
    1 <= c2 && c2 <= 8
)]
#[verus::ensures(result.len() == 3)]
#[verus::ensures(result[0] == rook_moves(r1, c1, r2, c2))]
#[verus::ensures(result[1] == bishop_moves(r1, c1, r2, c2))]
#[verus::ensures(result[2] == king_moves(r1, c1, r2, c2))]
fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    let mut res: Vec<i8> = Vec::new();
    // Rook
    res.push(rook_moves(r1, c1, r2, c2));
    // Bishop
    res.push(bishop_moves(r1, c1, r2, c2));
    // King
    res.push(king_moves(r1, c1, r2, c2));
    res
}

